import sys, json, time
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot,EpisodeOver
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares

CLOSE=np.array([1.0,0.2,1.1,0.,1.0,1.2,0.,1.1,0.8,1.2,0.,1.1,0.8,1.2,0.,1.1,0.8,0.1,1.2,0.,1.1,0.8])
CAMS=['front','oblique','top']
r=Robot(); spec=r.spec(); dt=spec['control_dt']

def obs(depth=True): return r.get_obs(cameras=CAMS,include_depth=depth)
def qnow(o): return np.array(o.meta['proprio']['now'][:29],float)
def send(q,t=1.,depth=True):
 o=r.submit('joint_position',np.asarray(q,float),dt=t,cameras=CAMS,include_depth=depth,video='frames')
 print('step',o.meta['control_steps'],'goal',o.meta['task']['goal_index'],'done',o.meta['done'],flush=True)
 return o

def point_cloud(o,c):
 a=o.last[c].astype(int); d=o.depth[c][-1].astype(float)
 h,w=d.shape;u,v=np.meshgrid(np.arange(w),np.arange(h));K=np.array(o.meta['cameras'][c]['intrinsic_cv']);M=np.array(o.meta['cameras'][c]['cam2world_gl']);
 p=np.stack([(u-K[0,2])/K[0,0]*d,-(v-K[1,2])/K[1,1]*d,-d,np.ones_like(d)],-1)@M.T
 return a,p[...,:3]

def marker_points(o,c='oblique'):
 a,p=point_cloud(o,c);x,y,z=np.moveaxis(p,-1,0)
 m=(x>-.23)&(x<.12)&(y>-.12)&(y<.2)&(z>.535)&(z<.6)&(a[:,:,0]<130)&(np.max(a,axis=2)-np.min(a,axis=2)<4)
 return p[m]

def report(o):
 print('q',np.round(qnow(o)[:7],4),'fingers',np.round(qnow(o)[7:],3),flush=True)
 for c in ['oblique','front']:
  p=marker_points(o,c)
  print(c,'marker',len(p),'median',np.median(p,axis=0) if len(p) else None,'span',np.percentile(p,[10,90],axis=0) if len(p) else None,flush=True)
 for c in CAMS:Image.fromarray(o.last[c]).save('/app/output/current_'+c+'.png')

if __name__=='__main__':
 o=obs();q=qnow(o);q[1]-=.1;q[7:]=CLOSE;send(q,t=1.5);o=obs();report(o)
